import Foundation

private typealias E = EvidenceSeed

/// Second follow-up trials for the batch L stories: the same defendant, back in this court.
extension FollowUpCases {
    static let batchBG: [CaseTemplate] = [hatchetDisputeAgain2, waterTowerClimbAgain2, inspectorCashAgain2, busDriverYellAgain2, streetRaceBystanderAgain2, scaleAndBagsAgain2, bankNoteRobberyAgain2, partyGrabAgain2, deletedServerAgain2, tailgateShoveAgain2, nightPharmacyAgain2, churchBooksAgain2, fireAlarmPullAgain2, snowbankAgain2, pillDiversionAgain2, longDriveAgain2, mercyKillingAgain2]

    static let hatchetDisputeAgain2 = SmallCases.make(
        key: "story.followup.hatchetDisputeAgain2",
        category: .violent,
        headlines: ["Surveyor Threatened With Axe Over Boundary Stakes", "Defendant From Driveway Case Charged With Assault Again"],
        law: "awdw",
        spec: "Assaulted {V}, a land surveyor, with a deadly weapon, an axe, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} swung an axe at {V}, a surveyor marking a boundary near {DL}'s new home. {V} jumped back and was not cut. {DL} says {D.he} only chopped the ground to scare off a trespasser.",
        state: [E(.video, 3, "Surveyor Camera", "{D} raises an axe and swings it toward {V}."), E(.physical, 2, "Axe", "An axe with fresh soil on the blade.", .search)],
        defense: [E(.statement, 1, "Chopped the Ground", "{DL} says the swing hit the dirt.")],
        role: "Land surveyor",
        exam: [.direct("What is your profession?", "\"I am a licensed land surveyor. I mark boundaries for landowners and lenders, and I was hired to stake the line near {DL}'s new home.\""),
               .direct("What were you doing that morning?", "\"I was setting stakes along the survey line with a handheld camera running on my vest. I had been working for about forty minutes before {DL} came out.\""),
               .direct("What happened when {DL} came out?", "\"{D.He} came across the yard carrying an axe and told me to get off the land. Then {D.he} raised the axe and swung it toward me.\""),
               .direct("How close did it come?", "\"I jumped back, and it came down hard where I had been standing a second earlier. Everything is on my camera, and I replayed it that night to be sure.\""),
               .direct("Were you cut?", "\"No, I was not cut. I stumbled and had a bruised hand from the fall, but the blade never touched me.\""),
               .direct("What did you do next?", "\"I backed away, called the sheriff's office, and kept the camera on until deputies arrived. {DL} went back toward the house with the axe.\""),
               .direct("What was on the axe when deputies found it?", "\"Fresh soil on the blade, which they photographed and collected. It matches the ground where the swing landed.\""),
               .cross("Did the axe hit the ground?", "\"Yes, it hit the ground, but only after I moved. If I had stood still, I believe it would have hit me.\""),
               .cross("Was {DL} clearing brush in the area?", "\"There was brush near the line, but {DL} was not working on it when I saw {D.him}. {D.He} came straight at me from the house.\""),
               .cross("You were on {DL}'s property, weren't you?", "\"I was along the boundary line, which is what I was hired to mark. I had a work order from the lender, and the stakes were on the survey line.\""),
               .cross("Did {DL} say anything about a trespasser?", "\"{D.He} said to get off the land. I identified myself as a surveyor and said I had a work order, and {D.he} did not seem to listen.\""),
               .cross("Could the swing have been meant for the ground?", "\"I cannot read {D.his} mind. I can only say the axe was raised toward me and came down where I had just been.\"")],
        theory: ("{D} swung an axe at a surveyor who was staking a boundary line.", "{D} chopped at the ground to scare off someone {D.he} took for a trespasser."),
        allocution: "\"I'm sorry for scaring the surveyor. I was clearing brush near my new home, and I chopped at the ground to scare off who I thought was a trespasser. I never swung at {V}. I'll hire a surveyor of my own and stay calm.\"",
        truths: ("{DL} had a prior case in this court and told {V} 'get off my land.'", "The axe landed a full arm's length from {V}, the video shows."),
        defendant: [.direct("What were you doing outside that morning?", "\"I was clearing brush near my new home with an axe. It was overgrown, and I wanted to open the line of sight to the road.\""),
               .direct("Did you see someone on your land?", "\"I saw a person near the edge of the property, and I did not know who it was. I did not know about any survey, and nobody told me.\""),
               .direct("What did you do?", "\"I walked toward the person, and I chopped at the ground to scare whoever it was off. I thought it was a trespasser.\""),
               .direct("Did you swing the axe at {V}?", "\"No, I swung it at the ground. I never intended to hit anyone, and I never aimed it at a person.\""),
               .direct("What did you say?", "\"I said something like get off my land. I was upset because I had been having trouble with people on the property.\""),
               .direct("What do you regret?", "\"I regret scaring {V}. I should have asked who it was before I did anything with an axe in my hand.\""),
               .cross("The video shows you raise the axe toward {V}, doesn't it?", "\"It shows me raising it, yes. But I brought it down on the dirt, and the video shows that too.\""),
               .cross("Fresh soil on the blade is what you would expect from chopping the ground, right?", "\"Yes, because the ground is where it went, and that is why I said so from the start.\""),
               .cross("You told {V} to get off your land, didn't you?", "\"I said that, yes. I did not know {V} was a surveyor, and I should have waited to find out.\""),
               .cross("You were in this court in {PRIORDATE} for {PRIOR}, weren't you?", "\"Yes, I was, and I know how that looks. It is why I should have stayed calm.\""),
               .cross("You had an axe in your hand in the middle of an argument with a stranger?", "\"Yes, I did, and it was a foolish thing to do. I was clearing brush when {V} came along the line.\"")],
        openings: ("A surveyor hired to mark a boundary was staking the line near {D}'s new home when {DL} came across the yard with an axe and swung it at {V}. {V} jumped back, the whole thing is on a camera, and {DL} was in this court before for {PRIOR}.", "The defense will present a homeowner who was clearing brush and chopped the ground to scare off someone {D.he} took for a trespasser. The axe hit dirt a full arm's length away, and nobody was touched."),
        closings: ("The video shows an axe raised and swung at {V}, and fresh soil on the blade. {V} jumped back and was not cut only because {V.he} moved.", "The video shows the axe landing on the ground a full arm's length from {V}. A warning chop at the dirt is not an assault, and the State has not shown {D} aimed it at a person."),
        timeline: [(-20, "A boundary dispute begins between {DL} and the neighbors over the survey line."), (0, "Morning: {V} is staking the line when {DL} comes across the yard with an axe."), (0, "{DL} swings the axe, {V} jumps back, and the surveyor's camera records it."), (0, "Deputies recover the axe with fresh soil on the blade.")],
        identified: "Surveyor Camera",
        aggravating: ["The offense involved a weapon"],
        mood: .wantsConviction)

    static let waterTowerClimbAgain2 = SmallCases.make(
        key: "story.followup.waterTowerClimbAgain2",
        category: .property,
        headlines: ["Teen Back on Roof of Abandoned Mill", "Second Trespass Charge for Climber From Tower Case"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a mill owner, after being notified not to enter, on {DATE}.",
        ages: 18...24,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} climbed onto the roof of a closed textile mill past a fence with posted signs. A neighbor called deputies. {DL} says the fence had a hole and the building looked abandoned.",
        state: [E(.physical, 3, "Fence and Signs", "A posted fence and a sign on the loading door."), E(.video, 2, "Phone Video", "{D} on the roof: 'this place is ours.'")],
        defense: [E(.statement, 1, "Hole in Fence", "{DL} says the fence had a gap.")],
        role: "Mill owner",
        exam: [.direct("What is your connection to the mill?", "\"I own the old textile mill. It has been closed for two years, but I still pay the taxes and the insurance, and I keep it secured.\""),
               .direct("How is the property secured?", "\"There is a chain-link fence around the whole lot, with posted no-trespassing signs, a padlock on the gates, and a sign on the loading door.\""),
               .direct("Who called deputies?", "\"A neighbor across the street saw someone on the roof around dusk and called. I was not there when it happened.\""),
               .direct("What did the phone video show?", "\"It shows {DL} standing on the roof saying this place is ours. A neighbor shared it with the deputies.\""),
               .direct("How did {DL} get onto the roof?", "\"There is a ladder bolted to the back wall, and the first rungs are about eight feet up. Someone climbed over the fence to reach it.\""),
               .direct("Was there damage?", "\"A skylight was cracked, and a section of flashing was bent. It cost me about $400 to patch before the next rain.\""),
               .direct("Why does it matter to you?", "\"The roof is not safe. Some of the decking is rotted, and a person could fall through, and I would be responsible.\""),
               .cross("Was there a gap in the fence?", "\"There was a small one near the back corner, yes, where a section had pulled away. I had planned to fix it.\""),
               .cross("So the fence was not entirely closed?", "\"A person could squeeze through that gap, but the gate was locked, and the signs were on the fence and the loading door.\""),
               .cross("Was every sign still in place that night?", "\"I am not sure. A sign may have fallen off the fence, but the one on the loading door was there.\""),
               .cross("Did you give {DL} permission?", "\"No. I do not know {D.him}, and I never gave anyone permission to go onto that roof.\""),
               .cross("Could someone think the building was abandoned?", "\"It is closed, so I understand why it might look that way. But it is not abandoned, and I own it.\"")],
        theory: ("{D} climbed onto the roof of a closed mill behind a posted fence.", "{D} went through a gap in a fence into a building that looked abandoned."),
        allocution: "\"There was a gap in that fence, and the old mill looked abandoned, and I climbed up to the roof without thinking. I saw one sign on a door and didn't take it seriously. I've been in this courtroom before about a climb, and I won't go near a building like that again.\"",
        truths: ("{DL} had a prior case in this court for climbing a tower.", "A sign had fallen off the fence and a worker later admitted the gap had been there for months."),
        defendant: [.direct("How did you get onto the mill property?", "\"There was a gap in the fence at the back corner. I walked through it, and I did not break anything.\""),
               .direct("Did you see any signs?", "\"One, on a door, and I did not take it seriously. I did not see signs along the fence.\""),
               .direct("Why did you go onto the roof?", "\"The building looked abandoned, and the view from up there looked interesting. I climbed up without thinking.\""),
               .direct("What did you say on the video?", "\"I said this place is ours, as a joke to my friend who was filming. I did not mean that I owned it.\""),
               .direct("Did you damage anything?", "\"No, I did not. I walked on the roof and came down when I saw the deputies.\""),
               .direct("How do you feel about it?", "\"I know I should not have gone up there. I am sorry to the owner and will not go near a building like that again.\""),
               .cross("You went through a fence, didn't you?", "\"Yes, through a gap. I did not climb over any locked gate.\""),
               .cross("You saw a sign on the loading door?", "\"I saw one sign, and I did not read it carefully. I did not think it applied.\""),
               .cross("You were in this court before, in {PRIORDATE}, for a climb, weren't you?", "\"Yes, I was, and I know I should have known better than to go up another structure.\""),
               .cross("You said this place is ours on the video, didn't you?", "\"I did, and it was a joke. It does not look like a joke when it is played in a courtroom.\""),
               .cross("You stayed on the roof until the deputies came?", "\"I stayed a few minutes. I came down when I saw the lights.\"")],
        openings: ("{V}'s closed textile mill is fenced and posted, with a padlocked gate and a sign on the loading door. A neighbor called deputies when {D} was seen on the roof, and a phone video shows {DL} saying this place is ours.", "The defense will present a fence with a gap in it and a building that looked abandoned. {D} walked through the opening, touched nothing, and came down when deputies arrived."),
        closings: ("There was a fence, a lock, signs, and a ladder bolted to the wall. {D} went through, climbed up, and filmed it. {D} had been here before for a climb.", "A gap in a fence, a sign that had fallen off, and a building that looked abandoned. The State has not shown that {D} knew {D.he} was not allowed there."),
        timeline: [(0, "Dusk: {D} goes through a gap in the fence behind the closed mill."), (0, "{D} climbs the bolted ladder to the roof and a friend films a phone video."), (0, "A neighbor calls deputies and {D} comes down when they arrive."), (1, "{V} finds a cracked skylight and bent flashing.")],
        identified: "A neighbor's call.",
        mood: .indifferent,
        genders: ["D": .male])

    static let inspectorCashAgain2 = SmallCases.make(
        key: "story.followup.inspectorCashAgain2",
        category: .whiteCollar,
        headlines: ["Zoning Officer Accepts $2,000 for Septic Sign-Off", "Former County Inspector Faces a New Bribery Charge"],
        law: "bribery",
        spec: "As a public officer, accepted cash from a landowner in exchange for approving a septic permit, on or about {DATE}.",
        ages: 40...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}, now a town zoning officer elsewhere, took $2,000 from a landowner for signing off on a septic permit that had failed a soil test. The landowner recorded the meeting. {DL} says the money paid for a site plan {D.he} drew on weekends.",
        state: [E(.video, 3, "Recorded Meeting", "{D} takes an envelope and says the permit will be fine."), E(.document, 2, "Soil Test", "The permit site failed a soil test the week before.")],
        defense: [E(.document, 1, "Site Plan Invoice", "An invoice for a drawn site plan for $2,000.")],
        role: "Town manager",
        exam: [.direct("What is your position?", "\"I am the town manager. I oversee all of the town departments, including the zoning and permit office.\""),
               .direct("What happened with the septic permit?", "\"A landowner's septic permit was signed off after the site had failed a soil test the week before. That should not have happened.\""),
               .direct("How did you learn about it?", "\"The landowner came to me, upset, and said {D} had taken $2,000 to approve it. The landowner had recorded the meeting on a phone.\""),
               .direct("What did the recording show?", "\"It shows {DL} taking an envelope across a table and saying the permit would be fine. I listened to it twice.\""),
               .direct("What was {DL}'s job?", "\"{D.He} was a town zoning officer. {D.His} duties included reviewing permit applications and the supporting tests.\""),
               .direct("What happened to the permit afterward?", "\"I had it pulled and the site retested. The retest passed, but the original sign-off was still improper.\""),
               .direct("Was there any other issue with {DL}?", "\"I learned later that {DL} had been in this court before as an inspector. That was not something anyone told me when {D.he} was hired.\""),
               .cross("Was there an invoice for the money?", "\"There is an invoice for a site plan. I first saw it after the recording came out, and I cannot say when it was written.\""),
               .cross("Does the town allow zoning officers to take side work?", "\"Not on matters that come before the office. A side job for someone with a pending application is a conflict.\""),
               .cross("The retest passed, didn't it?", "\"It did, and that matters to the landowner. It does not change what happened at the table.\""),
               .cross("Did you hear the whole conversation?", "\"Only the recording, which has background noise. It is clear enough to hear an envelope and the word fine.\""),
               .cross("You cannot say what was in the envelope, can you?", "\"No, only what the landowner and {DL} said about it. The landowner says it was $2,000.\"")],
        theory: ("{D} took cash from a landowner to approve a septic permit that had failed a soil test.", "{D} was paid for a weekend site plan and signed the permit after the soil retest passed."),
        allocution: "\"I'm sorry for how that meeting looked. The two thousand dollars was payment for a site plan I drew on weekends, and I never sold a signature. The soil retest passed. I've been in this courtroom before as an inspector, and I should have kept my side work completely separate.\"",
        truths: ("{DL} had a prior case in this court for taking cash from a contractor.", "The invoice was printed before the recorded meeting."),
        defendant: [.direct("What was the envelope?", "\"It was payment for a site plan I drew for the landowner on weekends. It was a side job, and I was paid for my work.\""),
               .direct("Why did you say the permit would be fine?", "\"The soil retest was coming back, and I expected it to pass. I was not promising anything.\""),
               .direct("Why did you do the job on the side?", "\"I draw plans on weekends to make extra money. I should have kept it separate from my work for the town.\""),
               .direct("Did you sell a signature?", "\"No, I did not sell a signature. I signed the permit when the retest came in.\""),
               .direct("Was there an invoice?", "\"Yes, I wrote one for the site plan. It was for $2,000, which is the same as what was in the envelope.\""),
               .direct("What would you do differently?", "\"I would have kept the side work completely separate from the town office. I am sorry for how the meeting looked.\""),
               .cross("You took $2,000 from a person with a permit pending before you, didn't you?", "\"Yes, I did, and I should not have done that. It was for a drawing, not for the permit.\""),
               .cross("The soil test failed the week before, didn't it?", "\"It did, and the retest passed. I signed it after that.\""),
               .cross("The recording has you saying it will be fine, doesn't it?", "\"It does, and I said it. I meant the retest would pass, not the permit would be bought.\""),
               .cross("You were in this court before as an inspector, weren't you?", "\"Yes, I was, in {PRIORDATE}, and I knew better than to mix the two. I regret that.\""),
               .cross("You did not report the side job to the town, did you?", "\"No, I did not report it, and I should have. I thought of it as separate work, and I did not see the conflict until this meeting was recorded.\"")],
        openings: ("A landowner's septic permit failed a soil test, and a week later a town zoning officer, {D}, took an envelope with $2,000 across a table and said the permit would be fine. The landowner recorded it, and {DL} had been in this court before as an inspector.", "The defense will present an invoice for a site plan {D} drew on weekends, and a soil retest that passed before the permit was signed. A side job paid in an envelope is not a bribe."),
        closings: ("A failed test, an envelope, and the words the permit will be fine, all on a recording. {D} was an inspector in this court before, and {D.he} knew better.", "An invoice, a drawn site plan, and a retest that passed. The State has a recording of an awkward meeting, not a sale of a signature."),
        timeline: [(-7, "The septic site fails a soil test."), (0, "The landowner meets {D} and records {D.him} taking an envelope with $2,000."), (3, "The soil retest passes and the permit is signed."), (10, "The landowner brings the recording to the town manager.")],
        identified: "A landowner's recording.",
        mood: .wantsConviction)

    static let busDriverYellAgain2 = SmallCases.make(
        key: "story.followup.busDriverYellAgain2",
        category: .publicOrder,
        headlines: ["Parent Blocks School Drop-Off Lane to Confront Principal", "Defendant From Bus Stop Case Charged Again"],
        law: "disorderly",
        spec: "Engaged in disorderly conduct by making a public disturbance in a school drop-off lane, on {DATE}.",
        ages: 24...55,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} stopped a car in a school drop-off lane on {DATE}, got out, and shouted at the principal for several minutes while a line of cars backed up. {DL} says the school ignored a complaint about a bully.",
        state: [E(.video, 3, "Drop-Off Camera", "{D} stands in the lane shouting as cars back up."), E(.statement, 2, "Principal", "The principal says {D} would not move for ten minutes.")],
        defense: [E(.document, 1, "Complaint Email", "{DL} emailed the school about a bully twice.")],
        role: "Elementary principal",
        exam: [.direct("What is your position?", "\"I am the principal of the elementary school. I have been at this school for eleven years.\""),
               .direct("What happened in the drop-off lane that morning?", "\"{DL} stopped a car in the middle of the lane, got out, and began shouting at me. The line of cars behind backed up all the way to the street.\""),
               .direct("What was {DL} shouting about?", "\"{D.He} said the school had ignored {D.his} complaints. {D.He} used loud language, and the children arriving could hear it.\""),
               .direct("How long did it go on?", "\"About ten minutes. I asked {D.him} several times to move the car and come inside to talk.\""),
               .direct("What does the drop-off camera show?", "\"It shows {DL} standing in the lane, waving arms and shouting, while cars stack up behind. It also shows me trying to talk to {D.him}.\""),
               .direct("Did {DL} move?", "\"Eventually, when a deputy was called. Until then {D.he} stood in the lane.\""),
               .direct("What was the effect on the school day?", "\"Parents were late, buses were delayed, and several children were upset. It disrupted the entire morning drop-off.\""),
               .cross("Did {DL} email the school before this?", "\"Yes, two emails about a bully, and I should have answered sooner. I did not see them until later.\""),
               .cross("Were the emails answered?", "\"Not by me. I handed them to a counselor, and I have not confirmed anyone replied.\""),
               .cross("Was {DL} threatening anyone?", "\"No, {D.he} did not threaten anyone. {D.He} was loud and angry, but I did not feel physically threatened.\""),
               .cross("Did the school respond to the bully complaint?", "\"We looked into it after this incident. I will not say we responded as quickly as we should have.\""),
               .cross("Were you outside the school grounds when it happened?", "\"The lane is on school property. It was on the school's drop-off route, under our control.\"")],
        theory: ("{D} stopped in a school drop-off lane and shouted at the principal while cars backed up.", "{D} was a parent whose complaints about a bully went unanswered and who lost patience."),
        allocution: "\"I called that school several times about a bully and no one answered, and I lost my patience and stopped in the drop-off lane to get someone out. I held up a line of parents, and I raised my voice. I've been in this courtroom before about a bus, and I'll handle it through the district.\"",
        truths: ("{DL} had a prior case in this court for a similar outburst at a bus.", "The school had indeed not answered the bully emails."),
        defendant: [.direct("Why did you stop in the lane?", "\"I called the school several times about a bully and nobody got back to me. I stopped to get someone to come out and talk to me.\""),
               .direct("What had you tried before that?", "\"I emailed twice and called three times. I got no answer, and my child kept coming home upset.\""),
               .direct("What did you shout?", "\"I raised my voice and told the principal the school was ignoring me. I used a couple of words I should not have.\""),
               .direct("Did you realize you were blocking cars?", "\"I did, and I did not care at the moment. I was only thinking about my child.\""),
               .direct("How long were you there?", "\"It felt like a few minutes, though the camera says ten. I moved when the deputy arrived.\""),
               .direct("What do you regret?", "\"I held up a line of parents, and that was unfair to them. I will handle it through the district from now on.\""),
               .cross("You stopped your car in a school drop-off lane, didn't you?", "\"Yes, I did, and I know it was wrong. I could have gone inside to ask.\""),
               .cross("You shouted at the principal in front of children, didn't you?", "\"I did, and I regret that the children heard it. I was angry and not thinking.\""),
               .cross("You were in this court before, in {PRIORDATE}, for an outburst at a bus, weren't you?", "\"Yes, I was, and that is why I should have known better.\""),
               .cross("The principal asked you to move the car, did the principal not?", "\"Yes, several times. I did not move it right away, because I was too angry to listen to anyone.\""),
               .cross("You could have waited for a call back, couldn't you?", "\"I could have, but I had already been waiting for weeks with no answer, and my child was coming home upset every single day.\"")],
        openings: ("For ten minutes one morning, {D} stopped in the school's drop-off lane, got out, and shouted at the principal while a line of cars backed up. A drop-off camera recorded it, and {DL} was in this court before for a similar outburst.", "The defense will present two unanswered emails about a bully and a parent who could not get anyone to listen. Loud words from a worried parent do not make a crime."),
        closings: ("The camera shows {D} in the lane, shouting, with cars backed up, for ten minutes. Children and parents watched, and {D} was in this court before for something similar.", "Two emails about a bully went unanswered. {D} stopped a car out of frustration, and the State has not shown that {D} meant to disturb anyone's peace."),
        timeline: [(-10, "{D} emails the school twice about a bully and gets no answer."), (0, "Morning: {D} stops a car in the school drop-off lane and shouts at the principal."), (0, "Ten minutes pass while cars back up and a deputy is called."), (0, "{D} moves the car when the deputy arrives.")],
        identified: "A drop-off camera.",
        mood: .indifferent,
        genders: ["D": .male, "V": .male])

    static let streetRaceBystanderAgain2 = SmallCases.make(
        key: "story.followup.streetRaceBystanderAgain2",
        category: .traffic,
        headlines: ["Racer Clocked at 112 on Interstate Exit Ramp", "Prior Race Defendant Cited for Reckless Driving Again"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others by racing another vehicle, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a trooper's dash camera caught {D} racing another car at 112 mph on an interstate exit ramp on {DATE}. {DL} says {D.he} was passing and the other car sped up.",
        state: [E(.video, 3, "Dash Camera", "Two cars side by side on the ramp at 112 mph."), E(.forensic, 2, "Radar Log", "112 mph in a 55 zone.")],
        defense: [E(.statement, 1, "Passing", "{DL} says {D.he} was passing a slow truck.")],
        role: "Highway Patrol trooper",
        exam: [.direct("What is your job?", "\"I am a Highway Patrol trooper. I patrol the interstate and its exit ramps, and I carry a radar unit and a dash camera.\""),
               .direct("What did you see that day?", "\"Two cars side by side on an exit ramp, both going very fast. The left one was {DL}'s.\""),
               .direct("How fast were they going?", "\"The radar showed 112 miles per hour. The ramp is posted at 55.\""),
               .direct("What does the dash camera show?", "\"It shows both cars even for the whole length of the ramp, with {DL}'s car in the left lane. The speed is on the screen.\""),
               .direct("Was there other traffic?", "\"There was a truck far ahead on the ramp, and a few cars on the interstate beyond. Both cars were closing on them fast.\""),
               .direct("What did you do?", "\"I activated my lights and followed them. They slowed together at the end of the ramp, and I stopped them both.\""),
               .direct("What did {DL} say?", "\"{D.He} said {D.he} was passing and the other car sped up. {D.He} did not deny the speed.\""),
               .cross("Was the truck close enough to pass?", "\"It was far ahead on the ramp. I do not think either car was passing it.\""),
               .cross("The other car sped up too, did it not?", "\"I could see both cars accelerating together. I could not tell which started first.\""),
               .cross("Did the other car swerve into {DL}'s lane?", "\"I did not see that. I am told {DL} says it did.\""),
               .cross("{DL} was braking when you lit them up, wasn't {D.he}?", "\"Both of them were slowing then. I cannot say who braked first.\""),
               .cross("You were not close enough to hear what was said between them, were you?", "\"No, I was behind them. I only know what the camera and radar show.\"")],
        theory: ("{D} raced another car on an exit ramp at 112 miles per hour.", "{D} was passing a truck when the other car sped up beside {D.him}."),
        allocution: "\"I was trying to pass on that exit ramp, and the other car sped up, and I went too fast. I've been in this courtroom before for racing, and I know I should have let it go. I'm sorry for the danger to everyone on that interstate, and I'll slow down.\"",
        truths: ("{DL} had a prior case in this court for a fatal race and texted 'one more run.'", "The other car swerved into {DL}'s lane without signaling."),
        defendant: [.direct("Were you racing the other car?", "\"No, I was not. I was passing, and the other car sped up beside me.\""),
               .direct("Why were you on the exit ramp?", "\"I was heading home and took the exit. I came up on a slow truck and moved to pass.\""),
               .direct("How fast were you going?", "\"Too fast. I do not dispute the radar, and I know that was dangerous.\""),
               .direct("What did the other car do?", "\"It sped up when I did, and it moved into my lane without signaling. I tried to stay clear of it.\""),
               .direct("Why did you not slow down sooner?", "\"I was concentrating on staying clear of the other car. I should have let it go.\""),
               .direct("What do you regret?", "\"I regret putting everyone on that interstate at risk. I will slow down.\""),
               .cross("The video shows both cars even for the whole ramp, doesn't it?", "\"It does, but they were even because the other car matched me. I did not plan to race.\""),
               .cross("You were going 112 in a 55, weren't you?", "\"Yes, I was, and there is no excuse for it. I do not dispute the radar, and I have thought about it every day since.\""),
               .cross("You were in this court before, in {PRIORDATE}, over a fatal race, weren't you?", "\"Yes, I was, and I know how it looks. I should have backed off the moment the other car did.\""),
               .cross("You texted someone one more run before this, didn't you?", "\"I texted a friend, but it was a joke. I was not talking about a race.\""),
               .cross("The truck was far ahead, wasn't it?", "\"It was, and I thought I could pass it. I misjudged how far.\"")],
        openings: ("A trooper's dash camera caught {D} and another car side by side on an interstate exit ramp at 112 miles per hour in a 55 zone. {DL} was in this court before over a fatal race, and the trooper's radar log agrees with the video.", "The defense will present a driver who came up on a truck, moved to pass, and found the other car speeding up beside {D.him}. A fast pass is not an agreed race."),
        closings: ("The video shows two cars even for the whole ramp at 112 miles per hour. The truck was far ahead, and {D} was in this court before for racing.", "A pass that went wrong, with another car that matched {D}'s speed and drifted into the lane. The State has not shown an agreement to race."),
        timeline: [(0, "Midday: {D} and another car come down an interstate exit ramp side by side."), (0, "A trooper's radar reads 112 miles per hour in a 55 zone and the dash camera records both cars."), (0, "The trooper stops both cars at the end of the ramp.")],
        identified: "A trooper's dash camera.",
        mood: .wantsConviction)

    static let scaleAndBagsAgain2 = SmallCases.make(
        key: "story.followup.scaleAndBagsAgain2",
