        role: "Sheriff's deputy",
        exam: [.direct("What is your assignment?", "\"I am a sheriff's deputy, and that weekend I was checking a county craft fair for permit violations and prohibited items.\""),
               .direct("What did you find at {DL}'s booth?", "\"A display case of jewelry, and in the lower shelf six glass pipes. Four of them had burn marks inside the bowl.\""),
               .direct("Why did that concern you?", "\"The organizer had told every vendor no smoking items. These were pipes, and the burn marks tell me they had been used.\""),
               .direct("What did the organizer say?", "\"The organizer said vendors were told in writing not to sell anything for smoking. The rule is in the vendor packet.\""),
               .direct("Did you speak with {DL}?", "\"Yes, {D.he} said they were art glass and not pipes. {D.He} showed me an invoice.\""),
               .direct("What did the invoice say?", "\"It listed six art glass pieces. It did not say pipes, and it did not say anything about use.\""),
               .direct("What did you do with the pieces?", "\"I seized them as evidence and submitted them for examination. I photographed them in place first.\""),
               .cross("The invoice calls them art glass, doesn't it?", "\"It does, and that is what {DL} told me. The question is what they are, not what the invoice calls them.\""),
               .cross("Did you see anyone buy one?", "\"No, I did not. I arrived after the fair opened, and nobody was at the booth at the time.\""),
               .cross("Could the burn marks have come from the glassblower?", "\"It is possible. A kiln can leave marks, but these looked to me like use.\""),
               .cross("Did you find any drugs?", "\"No, I did not. I found no residue in the booth, and nobody was charged with anything else.\""),
               .cross("You are not a glass expert, are you?", "\"No, I am not. I am telling you what I saw and what I know from my training.\"")],
        theory: ("{D} sold glass pipes in a craft fair booth.", "{D} sold art glass pieces that were mistaken for pipes."),
        allocution: "\"Those pieces in my booth are glass art, bought from the maker, and I never sold them as pipes. I've been in this courtroom before about a scale and bags, and I understand how it looks to a deputy. I'm sorry for the trouble at the craft fair.\"",
        truths: ("{DL} had a prior case in this court and a customer asked for a 'bowl.'", "The burn marks came from the glassblower's kiln, the maker later said."),
        defendant: [.direct("What do you sell at the fair?", "\"I sell jewelry, and I carry some glass art made by a local maker. I buy from the maker and mark it up.\""),
               .direct("Are those pieces pipes?", "\"No, they are art. They are sculptural pieces, and I have never sold one for smoking.\""),
               .direct("Where did the burn marks come from?", "\"From the maker. The kiln leaves marks, and the maker told me that when I bought them.\""),
               .direct("Did you have an invoice?", "\"Yes, I had an invoice for six art glass pieces. I showed it to the deputy.\""),
               .direct("Did anyone ask for a pipe or a bowl?", "\"Not that I remember. If someone did, I would have said these are art.\""),
               .direct("What do you regret?", "\"I regret the trouble at the craft fair. I understand how it looked to a deputy.\""),
               .cross("You had six glass pieces that look like pipes, didn't you?", "\"They look like pipes to a deputy. To me they are art glass.\""),
               .cross("You were in this court before, in {PRIORDATE}, for a scale and bags, weren't you?", "\"Yes, I was, and I know that is why they looked closely at me.\""),
               .cross("The organizer told vendors no smoking items, didn't she?", "\"Yes, and I did not think art counted. I should have asked.\""),
               .cross("A customer asked for a bowl, didn't they?", "\"One person used that word once. I told them I did not sell those.\""),
               .cross("You never asked the maker whether the pieces could be smoked, did you?", "\"No, I did not ask, because I was buying art and I took the maker at {D.his} word about what they were.\"")],
        openings: ("A deputy checking a craft fair found six glass pipes in a display case at {D}'s jewelry booth, four of them with burn marks. The organizer had told every vendor no smoking items, and {DL} was in this court before for {PRIOR}.", "The defense will present an invoice for six art glass pieces bought from a maker, and a kiln that explains the burn marks. A glass sculpture is not paraphernalia just because it looks like one."),
        closings: ("Six pipes in a jewelry booth, four with burn marks, under a no smoking rule. {D} had been here before for a scale and bags.", "The invoice says art glass and the maker says the marks came from the kiln. The State has not shown these were made or sold for smoking."),
        timeline: [(0, "A deputy checks a county craft fair for prohibited items."), (0, "The deputy finds six glass pieces in a display case at {D}'s jewelry booth."), (0, "{DL} shows an invoice for six art glass pieces, and the deputy seizes them.")],
        identified: "A deputy's booth check.",
        mood: .indifferent)

    static let bankNoteRobberyAgain2 = SmallCases.make(
        key: "story.followup.bankNoteRobberyAgain2",
        category: .robbery,
        headlines: ["Demand Note Passed to Check-Cashing Clerk", "Defendant From Bank Note Case Charged in New Robbery"],
        law: "commonLawRobbery",
        threshold: 7,
        spec: "Took $960 in United States currency from the person and presence of {V}, a check-cashing clerk, by putting {V.him} in fear, on {DATE}.",
        ages: 22...55,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a man passed a note to {V}, a clerk at a check-cashing store, on {DATE}: 'Fill the bag, stay quiet.' {V} handed over $960. A bus camera tracked a man to a stop where {D} was arrested. {DL} says {D.he} was riding home from a job.",
        state: [E(.video, 3, "Store Camera", "A man in a gray jacket hands a note and leaves with a bag."), E(.video, 3, "Bus Camera", "{D} boards a bus three blocks away with a bag.")],
        defense: [E(.document, 2, "Work Receipt", "A day-labor pay slip for that morning.")],
        role: "Check-cashing clerk",
        exam: [.direct("What is your job?", "\"I am a clerk at a check-cashing store. I have worked the counter there for four years.\""),
               .direct("What happened that afternoon?", "\"A man in a gray jacket came to my window and slid a note under the glass. It read fill the bag, stay quiet.\""),
               .direct("What did you do?", "\"I was scared, so I did what the note said. I put $960 in the bag and slid it back.\""),
               .direct("Did you see a weapon?", "\"No, I did not see one. He kept his hand in his jacket pocket the whole time.\""),
               .direct("How did you feel?", "\"Very afraid. I was shaking and my coworker had to take over the window afterward.\""),
               .direct("What did the store camera show?", "\"A man in a gray jacket handing over a note and leaving with a bag. The face is partly covered by a cap.\""),
               .direct("What did the police tell you later?", "\"They said a bus camera tracked a man with a bag to a stop where {D} was arrested. I did not see that part.\""),
               .cross("Could you see his face clearly?", "\"Not clearly. He wore a cap down low, and I mostly saw the jacket.\""),
               .cross("Did you pick {DL} out of a lineup?", "\"I was shown photos and I said he looked like the man, but I was not certain.\""),
               .cross("Did the man say anything?", "\"Only that I should hurry. He did not say anything more.\""),
               .cross("You never saw a weapon, did you?", "\"No, and I never saw anything in his hand besides the note.\""),
               .cross("Do you know whether {DL} owns a gray jacket?", "\"I do not know. I never saw {D.him} before that day.\"")],
        theory: ("{D} robbed a check-cashing clerk with a note.", "{D} was a day laborer riding a bus home from work."),
        allocution: "\"I was on a bus riding home from a job in my work clothes, and I never walked into that store. I've been in this courtroom before about a similar robbery, and I know it makes me look guilty. I hope the court studies the bus camera. I'm sorry for what that clerk went through.\"",
        truths: ("{DL} had a prior case in this court and a marked bill was in {D.his} pocket.", "The pay slip shows {DL} paid $90 that morning, in bills like the ones found."),
        defendant: [.direct("Did you rob the check-cashing store?", "\"No, I did not. I have never been inside that store, and I was on a bus on the other side of town when it happened.\""),
               .direct("Where were you that afternoon?", "\"I was on a bus riding home from a job. I had worked a day-labor shift that morning.\""),
               .direct("What was in your bag?", "\"My work clothes. I was carrying them home after the job.\""),
               .direct("Did you have a pay slip?", "\"Yes, a day-labor pay slip for that morning. It shows where I was working.\""),
               .direct("Why were you on that bus?", "\"It is the bus I take home from the labor office. I get on at the same stop every time.\""),
               .direct("What would you like the court to know?", "\"I would like the court to study the bus camera. I am sorry for what that clerk went through.\""),
               .cross("The bus camera shows you with a bag three blocks away, doesn't it?", "\"It shows me with my bag, which has my work clothes. I was coming home.\""),
               .cross("You were in this court before, in {PRIORDATE}, over a similar robbery, weren't you?", "\"Yes, I was, and I know that makes me look guilty. I did not do this one.\""),
               .cross("You were arrested at the bus stop, weren't you?", "\"Yes, police stopped me there. I told them where I had been working.\""),
               .cross("A marked bill was found in your pocket, wasn't it?", "\"I was paid in cash that morning, and I cannot say where the bills came from.\""),
               .cross("You have a gray jacket, don't you?", "\"I own one, and many people do. It was in my bag that day.\"")],
        openings: ("A man in a gray jacket passed {V} a note at a check-cashing window that read fill the bag, stay quiet, and left with $960. A bus camera tracked a man with a bag to a stop where {D} was arrested, and {DL} was in this court before for a similar robbery.", "The defense will present a pay slip from that morning and a bag of work clothes. A man on a bus with a bag is not a robber."),
        closings: ("A note, a gray jacket, and a bag that a bus camera followed to {D}. {D} had been in this court before for a similar robbery.", "A day laborer on a bus home with a bag of work clothes and a pay slip. The clerk could not see a face, and the State has not proved who held that note."),
        timeline: [(0, "Morning: {D} works a day-labor shift and is paid."), (0, "Afternoon: a man in a gray jacket passes {V} a note and leaves with $960."), (0, "A bus camera records {D} boarding three blocks away with a bag."), (0, "{D} is arrested at a bus stop later that afternoon.")],
        identified: "A store camera and a bus camera.",
        mood: .wantsConviction,
        genders: ["D": .male])

    static let partyGrabAgain2 = SmallCases.make(
        key: "story.followup.partyGrabAgain2",
        category: .family,
        headlines: ["Boyfriend Pulls Girlfriend by the Hair at Bowling Alley", "Defendant From House Party Case Charged With Assault on a Female"],
        law: "assaultFemale",
        spec: "Assaulted {V}, a female, being a male over eighteen years of age, on {DATE}.",
        ages: 20...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} grabbed {V}, {D.his} girlfriend, by the hair at a bowling alley on {DATE} and pulled {V.him} away from a lane. Staff saw it. {DL} says {D.he} was pulling {V.him} away from a spilled drink.",
        state: [E(.statement, 3, "Alley Staff", "{D} pulled {V} by the hair."), E(.forensic, 2, "Photos", "Redness at the scalp.")],
        defense: [E(.statement, 1, "Spill", "{DL} says there was a spill on the lane.")],
        role: "Bowling alley manager",
        exam: [.direct("What is your position at the bowling alley?", "\"I am the manager. I was on the floor that evening, and I was watching the lanes during the league night.\""),
               .direct("What did you see?", "\"I saw {DL} grab {V} by the hair and pull {V.him} away from a lane. It was sudden and it looked rough.\""),
               .direct("How did {V} react?", "\"{V.He} was crying and holding {V.his} head. {V.He} said it hurt and asked someone to call for help.\""),
               .direct("Who else saw it?", "\"Two staff members and several bowlers. Staff wrote down what they saw before the deputies came.\""),
               .direct("What injuries did you notice?", "\"There was redness at the scalp, which we photographed. {V.He} had a bruise by the temple.\""),
               .direct("What did {DL} say?", "\"I heard {D.him} say come here, now. {D.He} said it loudly, and then {D.he} pulled.\""),
               .direct("What did you do?", "\"I separated them, called the sheriff's office, and kept {DL} at the front until deputies came.\""),
               .cross("Was there a spill on the floor?", "\"There was a wet spot near the lane, but not where they were standing. It was a few feet away.\""),
               .cross("Could {DL} have been trying to move {V} from the spill?", "\"I did not see a reason to. {V} was not near it, and {DL} did not point to it.\""),
               .cross("Did {DL} hit {V}?", "\"I did not see a punch or a slap. I saw the hair grab and the pull.\""),
               .cross("Were they arguing before?", "\"I did not hear it. They were at the lane, and I saw the grab first.\""),
               .cross("You were across the room, weren't you?", "\"I was about thirty feet away, with a clear view. A staff member was closer.\"")],
        theory: ("{D} pulled {D.his} girlfriend by the hair at a bowling alley.", "{D} grabbed {V.him} to pull {V.him} away from a spilled drink."),
        allocution: "\"I grabbed {V} at that bowling alley, and I'm sorry. I meant to pull {V.him} away from a spilled drink on the floor, and I didn't think about how it looked. I've been in this courtroom before, and I know I should have used words. I'll never put my hands on {V.him} again.\"",
        truths: ("{DL} had a prior case in this court and a staff member heard {D.him} say 'come here, now.'", "A wet spot lay on the floor next to the lane, the staff photos show."),
        defendant: [.direct("Did you grab {V}?", "\"Yes, I grabbed {V.him}. I did not mean it to be rough.\""),
               .direct("Why did you do it?", "\"There was a spilled drink on the floor near the lane, and I wanted to pull {V.him} away before {V.he} slipped.\""),
               .direct("Did you grab {V.his} hair?", "\"I grabbed {V.him} by the head. I did not mean to pull hair, but I know that is what it looked like.\""),
               .direct("What did you say?", "\"I said come here, and I said it loud. I was scared that {V.he} would fall.\""),
               .direct("Did you hurt {V.him}?", "\"I know I did, and I am sorry. I did not mean to.\""),
               .direct("What do you regret?", "\"I should have used words. I will never put my hands on {V.him} again.\""),
               .cross("You pulled {V} by the hair, didn't you?", "\"I grabbed {V.him}, and I know it hurt. I did not do it to cause pain.\""),
               .cross("The spill was not where {V} stood, was it?", "\"It was close, and I thought it was in the way. I know now it was a few feet over.\""),
               .cross("Staff heard you say come here, now, didn't they?", "\"Yes, I said it, and I said it too loud. I was scared that {V.he} would slip, and it came out sharp.\""),
               .cross("You were in this court before, in {PRIORDATE}, for {PRIOR}, weren't you?", "\"Yes, I was, and I know that I should have been calm.\""),
               .cross("{V} was crying when you let go, wasn't {V.he}?", "\"Yes, {V.he} was, and I felt terrible about it right away. I tried to help {V.him} up and I said I was sorry.\"")],
        openings: ("At a bowling alley, {D} grabbed {V}, {D.his} girlfriend, by the hair and pulled {V.him} away from a lane while staff watched. The photos show redness at the scalp, and {DL} was in this court before for {PRIOR}.", "The defense will present a wet spot near the lane and a partner who grabbed in alarm, not anger. A clumsy grab meant to prevent a fall is not an assault."),
        closings: ("Staff saw {D} pull {V} by the hair away from the lane. {V} was crying and holding {V.his} head, the photos show redness at the scalp, and {D} had been in this court before.", "A spilled drink, a quick grab, and no blow struck. The State has not shown that {D} meant to hurt {V}, only that {D.he} acted too fast to think."),
        timeline: [(0, "Evening: {D} and {V} are at a bowling alley for league night."), (0, "{D} grabs {V} by the hair and pulls {V.him} away from the lane."), (0, "The manager separates them and calls the sheriff's office."), (0, "Staff photograph redness at {V.his} scalp.")],
        identified: "Alley staff.",
        mood: .wantsConviction,
        genders: ["D": .male, "V": .female])

    static let deletedServerAgain2 = SmallCases.make(
        key: "story.followup.deletedServerAgain2",
        category: .cyber,
        headlines: ["Former Contractor Locks Clinic's Appointment System With Leftover Password", "Prior Server Wipe Defendant Faces New Computer Charge"],
        law: "damagingComputers",
        spec: "Willfully and without authorization destroyed data on the computer network of a dental clinic, causing damage over $1,000.",
        ages: 30...50,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a dental clinic's scheduling database was wiped from a remote login on {DATE}. The login was a leftover contractor password issued to {D} years before. {DL} says the password was never revoked and others had it.",
        state: [E(.digital, 3, "Remote Login Log", "The contractor login deletes the database at 11:20 p.m."), E(.document, 2, "Repair Invoice", "$18,000 to restore appointments.")],
        defense: [E(.document, 1, "Unrevoked Password", "The clinic never changed passwords after the contract ended.")],
        role: "Clinic office manager",
        exam: [.direct("What is your position at the clinic?", "\"I am the office manager. I handle the scheduling system, the billing, and the outside vendors who work on our computers, so the database was my responsibility.\""),
               .direct("What happened to the database?", "\"Our scheduling database was wiped one night through a remote login. When we opened in the morning, two years of appointments were simply gone from the system.\""),
               .direct("Whose login was used?", "\"The old contractor login that was issued to {DL} years ago when {D.he} did work for us. It still had full administrator access on the day the database was deleted.\""),
               .direct("What did the log show?", "\"It shows the contractor login connecting from an outside address and deleting the database at 11:20 that night. There is nothing else on the account that evening.\""),
               .direct("What did it cost the clinic?", "\"$18,000 to have the appointments restored and the schedule rebuilt. My staff also spent days calling patients one at a time to confirm their visits.\""),
               .direct("How did patients react?", "\"Many were confused, some missed appointments, and a few were quite upset with us. We had to cancel two full days of work while we rebuilt the schedule.\""),
               .direct("Why was that login still active?", "\"We never changed the passwords after the contract ended, and that was our mistake. Nobody on my staff thought about an old account until this happened.\""),
               .cross("Was the contractor password ever changed after the contract ended?", "\"No, it never was. It stayed the same for years, and I did not know anyone had a reason to check it.\""),
               .cross("Did other people have that password?", "\"I do not know for certain. It was written on a document that went around to staff and vendors when we set up the system, so several people could have seen it.\""),
               .cross("Does the log show who was sitting at the keyboard?", "\"No, it shows only the account name, the address it connected from, and the time. It cannot tell me who used it.\""),
               .cross("Was {DL} still working for the clinic when this happened?", "\"No, the contract ended a few years before. I have no record of {D.him} being on site or contacting us since then.\""),
               .cross("Could anyone with that password have done this?", "\"Yes, I think anyone who had it could have. That is why we changed every password in the office the next morning.\"")],
        theory: ("{D} used an old contractor login to wipe a dental clinic's scheduling database.", "{D} never logged in that night, and the unrevoked password was available to other contractors."),
        allocution: "\"I'm sorry for what that clinic lost. I never logged in to wipe anything. That contractor password was never changed, and others had it. I've been in this courtroom before about a server, and I know my name is on the old login. I hope the court looks closely at who else had access.\"",
        truths: ("{DL} had a prior case in this court and a search for 'delete restore points' on {D.his} laptop.", "Another contractor used the same shared login and was seen on the log a week earlier."),
        defendant: [.direct("Did you log in to the clinic's system that night?", "\"No, I did not. I had not logged in to that system in years, and I had no reason to go near it.\""),
               .direct("Did you still have the password?", "\"I had it written down in an old notebook somewhere, but I never used it after the contract ended. I did not even know the account was still alive.\""),
               .direct("Why would you assume it had been shut off?", "\"When a contract ends, the client normally changes the passwords. I assumed the clinic did that, and nobody ever told me they had not.\""),
               .direct("Who else had the password?", "\"Other contractors did, because it was a shared login for the whole project. I do not know who used it after I left.\""),
               .direct("Where were you at 11:20 that night?", "\"I was at home that evening and I did not touch a computer. My family was with me, and I went to bed early.\""),
               .direct("What do you want the court to know?", "\"I did not wipe anything, and I am sorry for what the clinic lost. I hope the court looks closely at who else had access.\""),
               .cross("The login was issued in your name, wasn't it?", "\"It was issued to me years ago, but the same login was shared with other contractors, and the clinic never separated them out.\""),
               .cross("You were in this court before, in {PRIORDATE}, over a server, weren't you?", "\"Yes, I was, and I know my name on an old login will make people suspicious. I would never put my record at risk again.\""),
               .cross("Did you search for how to delete restore points on your laptop?", "\"I may have searched for something like that at some point, because I do this kind of work. That is not the same as doing it to this clinic.\""),
               .cross("Another contractor used the same shared login a week earlier, didn't he?", "\"I believe the log shows that, and I told the investigators about it. That is someone else who had the password and the access.\""),
               .cross("You never told the clinic to change the password, did you?", "\"No, I did not, and I should have. I left the project without reminding them, and I have thought about that since.\"")],
        openings: ("A dental clinic's scheduling database was deleted from a remote login at 11:20 one night, and the account used was the old contractor login issued to {D} years earlier. Restoring it cost $18,000, and {DL} was in this court before in {PRIORDATE} for {PRIOR}.", "Listen for what the clinic never did: it never changed that password. Several contractors shared it, a login is not a fingerprint, and the State cannot show who was at the keyboard."),
        closings: ("The login was {D}'s account, the deletion happened at 11:20 at night, and the repair cost $18,000. {D} had been in this court before over a server, and the account was never anyone else's by name.", "The clinic never changed the password, and it passed among contractors. A log shows an account and a time. It does not show a person, and the State has not shown that {D} typed those commands."),
        timeline: [(-1000, "{D} works as a contractor for the clinic and is issued a login that is shared on the project."), (0, "11:20 p.m.: the contractor login connects remotely and deletes the scheduling database."), (1, "The office manager opens the clinic and finds two years of appointments gone."), (5, "The clinic pays $18,000 to restore the database and rebuild the schedule.")],
        identified: "The remote login log.",
        mood: .indifferent)

    static let tailgateShoveAgain2 = SmallCases.make(
        key: "story.followup.tailgateShoveAgain2",
        category: .violent,
        headlines: ["Man Shoves Parking Attendant at Fairgrounds Lot", "Defendant From Tailgate Case Charged With Assault Again"],
        law: "simpleAssault",
        spec: "Assaulted {V}, a parking attendant, by shoving {V.him} with both hands, on {DATE}.",
        ages: 24...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} shoved {V}, a parking attendant at a county fairgrounds lot, on {DATE} after being told the lot was full. A camera caught the shove. {DL} says {V} stepped in front of {D.his} truck.",
        state: [E(.video, 2, "Lot Camera", "{D} shoves {V} back two steps."), E(.statement, 1, "Attendant", "{V} says {D} pushed {V.him} after being turned away.")],
        defense: [E(.statement, 2, "Truck Rolling", "{DL} says {V} stepped in front of the rolling truck.")],
        role: "Fairgrounds director",
        exam: [.direct("What is your position at the fairgrounds?", "\"I am the fairgrounds director. I oversee the events, the staff, and the parking lots, and I have held the job for six years.\""),
               .direct("Why was {V} at the lot gate that day?", "\"{V} works for us as a parking attendant. On a big event day {V.he} stands at the gate and directs cars into open rows or turns them away when we are full.\""),
               .direct("Was the lot full?", "\"Yes, it was full by mid-morning, and {V} was turning cars away on my instruction. We had put out signs about it at the road.\""),
               .direct("What does the lot camera show?", "\"It shows {DL}'s truck stopped at the gate and {V} standing in front of it. Then {DL} gets out and shoves {V} back two steps.\""),
               .direct("How did {V} react afterward?", "\"{V} was shaken and told me {V.he} had been pushed. {V.He} stayed on the job, but I could see that {V.he} was upset.\""),
               .direct("Did you hear {DL} say anything?", "\"Yes. I was at the office window, and I heard {D.him} curse at the gate before the shove. I could not make out every word.\""),
               .direct("What did you do?", "\"I told {V} to take a break, I called the sheriff's office, and I copied the camera footage. I wanted a record before anyone's story changed.\""),
               .cross("Did {V} step in front of the truck?", "\"On the camera I have, the angle is unclear. I cannot honestly say whether {V} was in front of the wheels or beside them.\""),
               .cross("Was the truck rolling when {DL} got out?", "\"A second angle I looked at later seems to show it moving about a foot. From the office window I could not see that.\""),
               .cross("Was {V} hurt?", "\"No. {V} was pushed back two steps and did not fall or get injured, and {V} was back at work the next day.\""),
               .cross("Was it a hard shove?", "\"It looks firm on the video, but not violent. {V} stepped back and kept {V.his} balance.\""),
               .cross("You were not at the gate, were you?", "\"No, I was inside the office and saw it through the window. What I know firsthand is the shove and the language, not the truck.\"")],
        theory: ("{D} shoved a parking attendant after being turned away from a full lot.", "{D} pushed the attendant back to keep a rolling truck from running over {V.his} foot."),
        allocution: "\"I pushed {V} back because my truck was rolling and {V.he} had stepped in front of it, and I was afraid it would run over a foot. I'm sorry that I shoved {V.him}. I've been in this courtroom before, and I know I should have set the brake and talked it out.\"",
        truths: ("{DL} had a prior case in this court and cursed at the gate.", "The truck did roll forward a foot when {V} stepped in, a second angle shows."),
        defendant: [.direct("Did you shove {V}?", "\"Yes, I pushed {V.him} back. I did not mean to hurt {V.him}, and I have never done anything like that at a gate before.\""),
               .direct("Why did you do it?", "\"My truck was rolling forward, and {V} had stepped in front of it. I was afraid it would run over {V.his} foot, so I reached out and pushed.\""),
               .direct("Did you set the brake?", "\"I should have, and I did not do it fast enough. I let up on the pedal while I was arguing, and the truck crept ahead.\""),
               .direct("What happened at the gate before that?", "\"I was told the lot was full after waiting in a long line. I was frustrated, and I cursed, which I am not proud of.\""),
               .direct("Was {V} hurt?", "\"No, thankfully. {V.He} stepped back two steps and seemed fine, and I told {V.him} I was sorry right away.\""),
               .direct("What do you regret?", "\"I regret that I put my hands on {V.him} at all. I should have set the brake and talked it out.\""),
               .cross("You were told the lot was full, weren't you?", "\"Yes, I was told twice. I did not want to hear it because I had driven a long way.\""),
               .cross("You cursed at the gate, didn't you?", "\"Yes, I did, and I am not proud of it. I was loud, and I was rude to someone who was only doing the job.\""),
               .cross("You were in this court before, in {PRIORDATE}, for {PRIOR}, weren't you?", "\"Yes, I was, and I know I should have stayed calm. I thought about it afterward and felt ashamed.\""),
               .cross("Your truck was rolling because you took your foot off the brake?", "\"I did let up on the brake, a little, while I was leaning out to argue. It crept forward about a foot.\""),
               .cross("{V} was not touching your truck when you shoved, was {V.he}?", "\"{V.He} had stepped right up to the bumper, which is why I pushed. I will not say {V.he} touched it, but {V.he} was in front of it.\"")],
        openings: ("A lot camera shows {D} getting out of a truck at a fairgrounds gate and shoving {V}, a parking attendant, back two steps after being told the lot was full. {DL} cursed at the gate, and {DL} was in this court before in {PRIORDATE} for {PRIOR}.", "Listen for the truck. A second camera angle shows it rolling forward a foot as {V} stepped in front of it. A push meant to save someone's foot is not an assault."),
        closings: ("The camera shows a shove at a gate after {D} was turned away, and {D} had been in this court before. The cursing and the push came from the same angry moment.", "A second angle shows the truck rolling a foot as {V} stepped in front of it. A push to protect a foot, with no injury and an apology, is not what this charge is meant to punish."),
        timeline: [(0, "Event day: the fairgrounds lot fills up by mid-morning and {V} turns cars away at the gate."), (0, "{D} reaches the gate in a truck and curses when told the lot is full."), (0, "The truck rolls forward as {V} steps in front, and {D} shoves {V} back two steps on camera."), (0, "The director calls the sheriff's office and saves the footage.")],
        identified: "A lot camera.",
        mood: .indifferent,
        genders: ["D": .male])

    static let nightPharmacyAgain2 = SmallCases.make(
        key: "story.followup.nightPharmacyAgain2",
        category: .property,
        headlines: ["Veterinary Clinic Burglarized Through Skylight; Controlled Drugs Taken", "Roofer From Pharmacy Case Linked to New Break-In"],
        law: "feloniousBE",
        threshold: 8,
        spec: "Broke and entered a veterinary clinic, a building in town, with the intent to commit larceny therein.",
        ages: 22...40,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a veterinary clinic was entered through a skylight on {DATE} and its controlled-drug cabinet emptied. {V}, the veterinarian, says {D}'s crew had repaired that roof a month before. A boot print on the counter matched {DL}'s boots. {DL} says the prints are from the repair job.",
        state: [E(.physical, 3, "Skylight and Prints", "A pried skylight and boot prints on the counter.", .search), E(.document, 3, "Roof Invoice", "{D}'s crew repaired the roof a month earlier."), E(.forensic, 2, "Tread Match", "The print matches {D}'s boots.")],
        defense: [E(.statement, 2, "Repair Job", "{DL} says the prints are from the repair visit.")],
        role: "Veterinarian",
        exam: [.direct("What kind of practice do you run?", "\"I am a veterinarian. I run a small animal clinic with two technicians, and we keep a locked cabinet for controlled drugs like sedatives and pain medicine.\""),
               .direct("What happened to your clinic?", "\"One morning I opened up and found the skylight pried open and the controlled-drug cabinet emptied. Everything in it was gone, including the sedatives.\""),
               .direct("What did you find on the counter?", "\"Boot prints, in dust and powder, on the counter right under the skylight. I did not touch them, and I called the sheriff's office immediately.\""),
               .direct("Who repaired your roof?", "\"{DL}'s crew repaired the roof about a month before the break-in. It had been leaking over the front room, and I hired them to fix it.\""),
               .direct("Did the crew come inside the clinic?", "\"Yes. They came in to use the bathroom a couple of times, and I let them through the back hall past that counter.\""),
               .direct("What did the roof invoice show?", "\"It shows the date of the job and the name of the crew, with {DL} listed as the owner of the roofing business. I gave it to the deputy.\""),
               .direct("What did the deputy tell you about the print?", "\"The deputy said the tread on the counter matches {DL}'s boots. That is what made me think of the repair job in the first place.\""),
               .cross("Could the prints have come from the repair visit?", "\"They could have, yes. The crew was inside at least once, and the prints might be from that day.\""),
               .cross("Did the crew walk past that counter?", "\"I do not remember exactly. The bathroom is down the hall, and that counter is on the way, so it is possible.\""),
               .cross("Did the prints look fresh to you?", "\"I am not an expert, but the deputy said they looked recent. I could not tell, because the dust on that counter is always heavy.\""),
               .cross("Did {DL} have a key to the roof hatch?", "\"I do not know. The hatch was locked, and I never gave anyone from the crew a key as far as I recall.\""),
               .cross("You cannot say who came through that skylight, can you?", "\"No, I only know what was left behind. I did not see anyone, and I was not there that night.\"")],
        theory: ("{D} used a roof {D.he} had repaired to break into a veterinary clinic and empty its drug cabinet.", "{D} left boot prints on an earlier repair job and never went through the skylight."),
        allocution: "\"I'm sorry for the break-in at that veterinary clinic. My crew repaired that roof a month before, and my boot prints are from that job. I never went through the skylight. I hope the court considers the repair records.\"",
        truths: ("{DL} had a prior case in this court and sold some of the drugs the next day.", "The prints were dust from the earlier job, and another crew member had a key to the roof."),
        defendant: [.direct("Did you break into that clinic?", "\"No. I have never been inside that building at night, and I did not go through that skylight.\""),
               .direct("Why would your boot prints be on the counter?", "\"My crew repaired that roof a month before, and we went in to use the bathroom. The prints are from that job, not from a break-in.\""),
               .direct("Did you have a key to the roof?", "\"No, I do not. Another crew member kept the key to the hatch, and I never carried one.\""),
               .direct("Where were you that night?", "\"I was at home with my family. I was nowhere near the clinic, and I can explain every hour of that evening.\""),
               .direct("Are those boots yours?", "\"Yes, I wear them on every job, and so do many roofers because it is a common brand. They are not special.\""),
               .direct("What would you tell the veterinarian?", "\"I am sorry for what happened to the clinic and the animals. I hope the court considers the repair records and where my boots had already been.\""),
               .cross("Your boots match the print, don't they?", "\"They match the tread, but my crew was inside that building a month earlier, and those same boots walked through it.\""),
               .cross("You were in this court before, in {PRIORDATE}, weren't you?", "\"Yes, I was, and I know that history makes people look at me first. That does not make me the person who did this.\""),
               .cross("You sold some of the drugs the next day, didn't you?", "\"No, I did not. I have never sold anything like that, and no one has shown otherwise.\""),
               .cross("Your crew knew about the skylight, didn't they?", "\"They did, because we had just repaired the roof around it. That is exactly why it was a weak spot for anyone who knew it.\""),
               .cross("Another crew member had a key, didn't he?", "\"Yes, I believe he kept the key to the hatch, though I cannot say where it was on the night of the break-in.\"")],
        openings: ("A veterinary clinic's controlled-drug cabinet was emptied through a pried skylight, and a boot print on the counter matches {D}'s boots. {D}'s crew had repaired that very roof a month earlier, and {DL} was in this court before in {PRIORDATE} for {PRIOR}.", "The defense will present a repair job that explains the boots and a crew member who held the key to the roof. A print does not say when it was left, and a boot that was inside a month ago proves nothing about that night."),
        closings: ("A pried skylight, a boot print on the counter, and a roofer who knew exactly how that roof was built. {D} had been in this court before, and the tread matches.", "The prints came from a job a month earlier, and another person had the key. The State has not shown when that boot touched the counter, or that {D} was there that night."),
        timeline: [(-30, "{D}'s crew repairs the clinic's leaking roof and uses the bathroom inside."), (0, "Night: someone pries the skylight open and empties the controlled-drug cabinet."), (1, "The veterinarian finds the open skylight and boot prints on the counter and calls the sheriff."), (5, "A deputy's tread comparison matches the print to {D}'s boots.")],
        identified: "A tread match and a roof invoice.",
        mood: .wantsConviction)

    static let churchBooksAgain2 = SmallCases.make(
        key: "story.followup.churchBooksAgain2",
        category: .whiteCollar,
        headlines: ["Volunteer Fire Department Treasurer Accused of $38,000 Shortfall", "Treasurer From Church Fund Case Charged Again"],
        law: "embezzlement",
        spec: "As treasurer, embezzled $38,000 from a volunteer fire department.",
        ages: 44...63,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}, the volunteer treasurer of a fire department, was found short $38,000 after a fish fry fund drive. Transfers went to {DL}'s account. {DL} says the transfers repaid out-of-pocket purchases.",
        state: [E(.document, 3, "Bank Transfers", "$38,000 in transfers to {D}'s personal account."), E(.document, 2, "Audit", "No receipts for most purchases.")],
        defense: [E(.document, 1, "Receipts", "A few receipts for hoses and fuel.")],
        role: "Fire chief",
        exam: [.direct("What is your role at the fire department?", "\"I am the fire chief. I have run the department for nine years, and I answer to the board and to the families who give us their money and time.\""),
               .direct("What was {DL}'s role?", "\"{D.He} was our volunteer treasurer. {D.He} ran the fish fry fund drive and kept the department's checking account.\""),
               .direct("What was missing?", "\"After the fish fry, the audit found the account short by $38,000. We had counted on that money for equipment and a new tank.\""),
               .direct("Where did the money go?", "\"The bank records show transfers to {DL}'s personal account in the weeks after the fund drive. The transfers add up to the full $38,000.\""),
               .direct("What does the audit show about receipts?", "\"There are no receipts for most of the purchases. A few receipts exist for hoses and fuel, and they come to a small part of the total.\""),
               .direct("Who had access to the account?", "\"{DL} and our board secretary were on the account, but only {DL} made transfers. The secretary never moved a dollar.\""),
               .direct("How did the department react?", "\"We were stunned. Many members gave their weekends to that fund drive, and some talked about quitting when the audit came out.\""),
               .cross("Were there any receipts at all?", "\"A few, for hoses and fuel, and they come to about $6,000. That is a small fraction of what was moved.\""),
               .cross("Could {DL} have been reimbursed for out-of-pocket purchases?", "\"For some purchases, maybe, but not $38,000 and not without receipts. The board approved only a few small reimbursements.\""),
               .cross("Did the board approve those transfers?", "\"No, the board did not approve them. Some small ones were approved in the past, but not these.\""),
               .cross("Did {DL} tell you about the transfers before the audit?", "\"No. {D.He} said nothing until the audit came out, and then {D.he} said they were repayments for things {D.he} had bought.\""),
               .cross("You do not know what {DL} actually bought, do you?", "\"No, and that is the problem. We asked for receipts and got a few, and I cannot say what the rest was for.\"")],
        theory: ("{D} treated a volunteer fire department's fund as a personal account once again.", "{D} moved money to {D.his} own account to repay purchases {D.he} made for the department."),
        allocution: "\"I'm sorry for the shortage in our fire department's account. The transfers to me repaid purchases I made out of my own pocket for the fish fry, and I was repaid for some of them. I've been in this courtroom before as a treasurer, and I should have kept receipts. I'll account for every dollar.\"",
        truths: ("{DL} had a prior case in this court and a spreadsheet of personal bills.", "Fuel and hose receipts in {DL}'s truck totaled $6,000."),
        defendant: [.direct("Did you take the department's money?", "\"No, I did not. I was repaid for purchases I made out of my own pocket for the fish fry and other department needs.\""),
               .direct("What did you buy?", "\"Hoses, fuel, and supplies for the fish fry. I used my own money because the department needed things quickly and I did not want to wait for a board meeting.\""),
               .direct("Do you have receipts?", "\"Some. The fuel and hose receipts are in my truck, and they total about $6,000, which I gave to the auditor.\""),
               .direct("Why do you not have receipts for the rest?", "\"I did not keep all of them, and I should have. I was careless about paperwork, and I know that is a poor excuse.\""),
               .direct("Did the board approve each transfer?", "\"Not each one. I believed it was understood that I would be repaid, and I did not ask for a vote every time.\""),
               .direct("What will you do now?", "\"I will account for every dollar I can, and I will pay back whatever cannot be accounted for. I am sorry for the shortage.\""),
               .cross("$38,000 went into your personal account, didn't it?", "\"Yes, it went into my account, but I believed it was repayment for what I had spent. I did not think of it as taking.\""),
               .cross("You were in this court before, in {PRIORDATE}, as a treasurer, weren't you?", "\"Yes, I was, and I should have been far more careful with records because of it. I let that lesson slip.\""),
               .cross("You kept a spreadsheet of your personal bills, didn't you?", "\"I keep one for my own household, and it is separate from the department's account. It does not show the department paying my bills.\""),
               .cross("Your receipts total about $6,000, don't they?", "\"Yes, that is what I have found so far, and I am still looking. The rest I will have to reconstruct from bank records.\""),
               .cross("You never asked the board before moving that much money, did you?", "\"No, I did not, and that was a mistake. A treasurer should never move money like that without a vote.\"")],
        openings: ("A volunteer fire department was short $38,000 after a fish fry fund drive, and every dollar went by bank transfer to its treasurer, {D}. The audit found no receipts for most of it, and {DL} was in this court before in {PRIORDATE} for {PRIOR}.", "Listen for the receipts for hoses and fuel and a treasurer who paid for the department out of pocket. Poor record keeping is a failure of bookkeeping, and the State must prove it was a fraud."),
        closings: ("The money went from the department's account to {D}'s account, in transfers {D} alone made, and almost nothing was documented. {D} had been in this court before as a treasurer.", "Receipts for hoses and fuel, repayments for purchases, and a volunteer who kept poor books. That is carelessness, and the State has not proved that {D} meant to keep what was not owed."),
        timeline: [(-30, "The fire department holds its fish fry fund drive."), (0, "The audit shows the department's account is $38,000 short."), (0, "Bank records show the transfers to {D}'s personal account."), (5, "{D} produces receipts for hoses and fuel that total about $6,000.")],
        identified: "A department audit.",
        mood: .wantsConviction)

    static let fireAlarmPullAgain2 = SmallCases.make(
        key: "story.followup.fireAlarmPullAgain2",
        category: .publicOrder,
        headlines: ["911 Caller Reports Smoke in Neighbor's Apartment, Engines Find Nothing", "Tenant From False Alarm Case Charged With False Report"],
        law: "falseReport",
        spec: "Willfully made a false report to a law enforcement agency that a building was on fire, on {DATE}.",
        ages: 20...50,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a 911 caller reported smoke pouring from a neighbor's apartment on {DATE}. Engines found no fire. The call came from a number linked to {D}. {DL} says {D.he} smelled burning toast and panicked.",
        state: [E(.digital, 3, "911 Recording", "A caller reports smoke and screaming."), E(.document, 2, "Fire Log", "Two engines; no fire found.")],
        defense: [E(.statement, 1, "Burnt Toast", "{DL} says {D.he} smelled something burning.")],
        role: "Fire captain",
        exam: [.direct("What is your position at the fire department?", "\"I am a fire captain. I was in command of the engines that responded that night, and I wrote the incident report.\""),
               .direct("What was reported to dispatch?", "\"A 911 caller said smoke was pouring from a neighbor's apartment and that someone was screaming. We sent two engines and a ladder crew on that information.\""),
               .direct("What did you find when you arrived?", "\"No fire, no smoke, and nobody screaming. We went door to door and checked every unit in the building, and everything was normal.\""),
               .direct("How long were the crews tied up?", "\"About an hour. That is an hour when those engines could not respond to a real emergency elsewhere in the county.\""),
               .direct("Whose number placed the call?", "\"The call traced to a number that belongs to {DL}. The dispatch recording and the trace record both show it.\""),
               .direct("What did the neighbor say?", "\"The neighbor said nothing was wrong and was upset about being woken. They said they had been home and had not smelled anything.\""),
               .direct("Was there anything burning in the building?", "\"A toaster in the unit next door had burned toast earlier in the day. There was a faint odor in the hall near that unit, but no smoke.\""),
               .cross("Could someone smell burning toast from the hall?", "\"It is possible. It is a small building with thin walls, and a faint odor does carry into the hall.\""),
               .cross("Did the caller sound frightened?", "\"Yes, on the recording the caller sounds frightened and out of breath. It was convincing enough that we rolled everything.\""),
               .cross("Was there any smoke in the hall when you arrived?", "\"No, only a faint odor near the toaster. Nothing that would look like smoke pouring out of an apartment.\""),
               .cross("Did you speak with {DL} that night?", "\"Briefly. {D.He} told me {D.he} had smelled something burning and panicked. I did not take a long statement.\""),
               .cross("You cannot say who was speaking on the call, can you?", "\"I can say the number the call came from. I cannot say who held the phone, and I did not listen for a voice match.\"")],
        theory: ("{D} made a false 911 report about smoke at a neighbor's apartment.", "{D} smelled burning toast and called in a panic without meaning to deceive anyone."),
        allocution: "\"I smelled smoke that night and called 911 in a panic, and it was burning toast. I'm sorry for the three engines and the trouble to my neighbor. I've been in this courtroom before about a false alarm, and I should have knocked on the door first.\"",
        truths: ("{DL} had a prior case in this court and argued with that neighbor earlier that day.", "The neighbor had burned toast that morning, the toaster showed."),
        defendant: [.direct("Did you call 911 that night?", "\"Yes, I did. I smelled smoke in the hall and I panicked and called without thinking about what else I could do.\""),
               .direct("What did you smell?", "\"Something burning, strong enough that I thought a unit was on fire. I did not know then that it was toast.\""),
               .direct("Why did you call 911 instead of knocking on the door?", "\"I was scared and I did not think clearly. I wish I had knocked on the door first and asked the neighbor.\""),
               .direct("What did you say to the dispatcher?", "\"I said there was smoke and I thought someone was screaming. I was upset, and I may have exaggerated what I heard.\""),
               .direct("Did you have a problem with the neighbor?", "\"We had argued earlier that day about parking. It was a small thing, and I would never use a fire call to get back at anyone.\""),
               .direct("What do you regret?", "\"I am sorry for the two engines and the trouble to my neighbor. I should have checked before I called.\""),
               .cross("You argued with that neighbor earlier that day, didn't you?", "\"Yes, about parking spaces, and it was a loud argument. That has nothing to do with the smell I noticed later.\""),
               .cross("You were in this court before, in {PRIORDATE}, over a false alarm, weren't you?", "\"Yes, I was, and I should have knocked first this time. I know how a second call looks.\""),
               .cross("There was no screaming, was there?", "\"I thought I heard it, but it may have been a television. I was frightened and I did not stop to listen.\""),
               .cross("The fire log shows no fire at all, doesn't it?", "\"Yes, it does, and it turned out to be burned toast. I was wrong, and I am sorry.\""),
               .cross("You called from your own phone, didn't you?", "\"Yes, I did, and I gave my own name when the dispatcher asked. I did not try to hide who I was.\"")],
        openings: ("A 911 caller reported smoke pouring from a neighbor's apartment and someone screaming, and two engines found no fire at all. The call traced to {D}'s phone, {DL} had argued with that neighbor that day, and {DL} was in this court before in {PRIORDATE} for {PRIOR}.", "The defense will present a person who smelled something burning, called out of fear, and gave a true name to the dispatcher. A mistaken call made in panic is a mistake, not a lie."),
        closings: ("Two engines, an hour of lost time, and a call from {D}'s phone hours after an argument with the neighbor. {D} had been in this court before over a false alarm.", "A burned toaster and a frightened call, from someone who gave a real name. The State has not shown that {D} knew there was no fire when {D.he} picked up the phone."),
        timeline: [(-1, "{D} argues with the neighbor about parking spaces."), (0, "Evening: {D} calls 911 reporting smoke and screaming at the neighbor's apartment."), (0, "Two engines and a ladder crew respond and find no fire."), (0, "The dispatch log traces the call to {D}'s phone.")],
        identified: "A 911 recording.",
        mood: .wantsConviction)

    static let snowbankAgain2 = SmallCases.make(
        key: "story.followup.snowbankAgain2",
        category: .traffic,
        headlines: ["Driver Hits Cyclist in Sleet and Drives Off", "Defendant From Culvert Case Charged With Leaving the Scene"],
        law: "hitAndRun",
        threshold: 8,
        spec: "Left the scene of a crash causing serious injury without stopping, on {DATE}.",
        ages: 33...46,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a cyclist, {V}, was struck on an icy road on {DATE} by an SUV that did not stop. A bumper fragment matched {D}'s SUV. {DL} says {D.he} thought {D.he} had hit a snowbank.",
        state: [E(.physical, 3, "Bumper Fragment", "A fragment at the scene matches {D}'s SUV.", .search), E(.forensic, 3, "Medical Report", "A broken collarbone and head injury."), E(.video, 2, "Farm Camera", "An SUV slows and drives on.")],
        defense: [E(.statement, 1, "Snowbank", "{DL} says the thud felt like a snowbank.")],
        role: "Highway Patrol trooper",
        exam: [.direct("What is your job?", "\"I am a Highway Patrol trooper, and I investigate crashes and hit-and-runs on the county roads.\""),
               .direct("What did you find at the scene?", "\"A bumper fragment lying in the road and a cyclist in the ditch. {V} was conscious but badly hurt and cold.\""),
               .direct("What were {V}'s injuries?", "\"A broken collarbone and a head injury. {V} was taken to the hospital by ambulance, and the medical report is in the file.\""),
               .direct("Where was the cyclist when it happened?", "\"On the right side of an icy county road, before dawn. The road had a light dusting of snow and patches of ice.\""),
               .direct("What did the farm camera show?", "\"An SUV slowing as it passes the camera and then driving on. It is dark, but you can see the shape and the headlights.\""),
               .direct("How did you connect the fragment to {DL}?", "\"The fragment fits a missing piece on the front bumper of {D}'s SUV. I found the SUV at {D.his} home that morning with the bumper damaged.\""),
               .direct("What did {DL} tell you?", "\"{D.He} said {D.he} had felt a thud on the icy road and thought {D.he} hit a snowbank. {D.He} said {D.he} did not know it was a person.\""),
               .cross("Was it dark when this happened?", "\"Yes, it was before dawn and still dark. The sun did not come up for another hour.\""),
               .cross("Was the cyclist wearing lights or reflective clothing?", "\"I did not find any lights on the bicycle. {V} was wearing dark clothing, which made {V.him} hard to see.\""),
               .cross("Was the road slick?", "\"Yes, there were icy patches in several places, and I had to drive carefully myself to reach the scene.\""),
               .cross("Was there a snowbank near the spot?", "\"There was a plowed snowbank along the shoulder not far away. Someone might have taken a thud for that.\""),
               .cross("Does the farm camera show the SUV stopping?", "\"No, it shows the SUV slowing down and then going on. It does not show it stopping or turning around.\"")],
        theory: ("{D} struck a cyclist on an icy road before dawn and drove on without stopping.", "{D} felt a thud and honestly took it for a snowbank."),
        allocution: "\"I thought I'd hit a snowbank on that icy road. I felt a thud and didn't know it was a person. I'm so sorry to {V}, and I hope {V.he} recovers. I've been in this courtroom before about a similar night, and I should have stopped and checked.\"",
        truths: ("{DL} had a prior case in this court and looked in the mirror before driving on.", "The cyclist wore dark clothing and had no lights."),
        defendant: [.direct("Did you stop that night?", "\"No, I did not. I felt a thud and thought I had clipped the snowbank along the shoulder.\""),
               .direct("What did you feel?", "\"A thud against the front of the SUV. The road was icy, and the steering jerked, and I was concentrating on keeping control.\""),
               .direct("Did you look back?", "\"I glanced in the mirror and saw only darkness. I did not see a person, so I kept driving and went home.\""),
               .direct("When did you learn what had happened?", "\"When the trooper came to my house that morning and showed me the fragment. I was horrified.\""),
               .direct("What do you want {V} to know?", "\"I am so sorry, and I hope {V.he} recovers fully. I would never have driven on if I had known it was a person.\""),
               .direct("What do you wish you had done?", "\"I wish I had stopped and checked right then. I should have gotten out and looked, even in the dark.\""),
               .cross("You felt a thud, didn't you?", "\"Yes, I felt it and I heard it, and I did not stop to find out what it was. I am sorry for that.\""),
               .cross("You were in this court before, in {PRIORDATE}, after a similar night, weren't you?", "\"Yes, I was, and I should have stopped for that reason. I know how it looks.\""),
               .cross("It was icy and you were driving too fast for it, weren't you?", "\"I was driving as carefully as I could, but the road was bad. I may have been going faster than I should have.\""),
               .cross("Your bumper was damaged when the trooper found it, wasn't it?", "\"Yes, it was cracked, and I had not looked at it before the trooper arrived. I thought it was from the snowbank.\""),
               .cross("You did not report it or call anyone, did you?", "\"No, I did not, and I regret it. I did not know there was anything to report.\"")],
        openings: ("Before dawn on an icy county road, an SUV struck a cyclist, {V}, and did not stop. A bumper fragment at the scene fits {D}'s SUV, a farm camera caught it driving on, and {DL} was in this court before in {PRIORDATE} for {PRIOR}.", "The defense will present a driver who felt a thud on an icy road and took it for a snowbank, and a cyclist in dark clothing with no lights. Knowledge is the key, and {D} did not know a person was there."),
        closings: ("A bumper fragment, a farm camera, and a cyclist in a ditch with a broken collarbone. {D} felt the impact and kept going, and had been in this court before.", "A thud in the dark, an icy road, and a snowbank nearby. The State has not shown that {D} knew {D.he} had struck a person."),
        timeline: [(0, "Before dawn: an SUV strikes a cyclist on an icy county road and drives on."), (0, "A farm camera records the SUV slowing and then continuing."), (0, "A trooper finds the bumper fragment and the injured cyclist in the ditch."), (1, "The trooper finds {D}'s SUV with a damaged bumper that fits the fragment.")],
        identified: "A bumper fragment.",
        mood: .wantsConviction)

    static let pillDiversionAgain2 = SmallCases.make(
        key: "story.followup.pillDiversionAgain2",
        category: .drugs,
        headlines: ["Dental Assistant Takes Hydrocodone From Locked Cabinet", "Technician From Pill Case Hired at a Dental Office"],
        law: "possSchedII",
        spec: "Possessed a Schedule II controlled substance, hydrocodone, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a dental office counted 40 hydrocodone tablets missing on {DATE}. A camera showed {D}, an assistant, opening the locked cabinet. Tablets were in {D.his} bag. {DL} says {D.he} was restocking the cabinet.",
        state: [E(.video, 3, "Office Camera", "{D} opens the cabinet and pockets a bottle."), E(.physical, 3, "Bag Tablets", "Twelve hydrocodone tablets in {D}'s bag.", .search)],
        defense: [E(.statement, 1, "Restocking", "{DL} says {D.he} was restocking.")],
        role: "Dentist",
        exam: [.direct("What kind of practice do you run?", "\"I am a dentist. I run a small office with two assistants and a front desk, and we keep controlled drugs in a locked cabinet.\""),
               .direct("What did you find missing?", "\"During a count I found forty hydrocodone tablets missing from that cabinet. The count log and the inventory sheet did not agree.\""),
               .direct("Who had the key to the cabinet?", "\"{DL} and I are the only two with keys. {D.He} is my assistant, and {D.he} opens the cabinet when I ask for supplies.\""),
               .direct("What does your office camera show?", "\"It shows {DL} opening the cabinet and pocketing a bottle. The camera points at the supply room, and the picture is clear.\""),
               .direct("What was found in {DL}'s bag?", "\"Twelve hydrocodone tablets were in {D.his} bag when a deputy searched it. They were loose, not in a labeled bottle.\""),
               .direct("Is restocking part of {DL}'s duties?", "\"Sometimes, yes. {D.He} puts supplies away, but I usually handle the controlled drugs myself.\""),
               .direct("How did you feel when you saw this?", "\"I was shocked, because I trusted {D.him}. I had never had a reason to doubt {D.him}.\""),
               .cross("Was your count off before this?", "\"Yes, my own log was off by ten tablets the week before. I did not find out why.\""),
               .cross("Does your log have mistakes?", "\"Sometimes. I keep it by hand, and I may have written something wrong.\""),
               .cross("Did {DL} have a reason to open that cabinet?", "\"Yes, to restock supplies, though not usually the drugs. That day I had asked for gauze.\""),
               .cross("Did {DL} tell you about the bottle?", "\"No, {D.he} never mentioned it. I learned about it from the camera.\""),
               .cross("You cannot say exactly how many were taken, can you?", "\"Forty is my count from the log. The log was off the week before, so I cannot be certain.\"")],
        theory: ("{D} took hydrocodone tablets from a locked dental cabinet.", "{D} was restocking the cabinet with full hands and took nothing."),
        allocution: "\"I was restocking that cabinet when the pills ended up in my bag, because my hands were full. I never took them. I've been in this courtroom before about pills, and I know how that looks on camera. I'm sorry to the dentist and the patients, and I'll cooperate fully.\"",
        truths: ("{DL} had a prior case in this court and had not told the dentist.", "The dentist's own count log was off by ten the week before."),
        defendant: [.direct("Did you take any pills?", "\"No, I did not. I have never taken anything from that office.\""),
               .direct("Why did you pocket the bottle?", "\"My hands were full of supplies, and I put it in my pocket for a second to carry it to the cabinet. I was not hiding it.\""),
               .direct("What were you doing in that room?", "\"I was restocking the cabinet after a delivery. The dentist had asked me to put the order away.\""),
               .direct("Where did the tablets in your bag come from?", "\"I do not know how they got there. I put things in that bag every day, and I did not notice them until the deputy found them.\""),
               .direct("Did you tell the dentist?", "\"I should have told the dentist about the bottle at once. I did not think it mattered because I was just putting it away.\""),
               .direct("What do you want the court to know?", "\"I did not steal anything. I am sorry for the worry this caused, and I will cooperate fully.\""),
               .cross("You pocketed a bottle of hydrocodone, didn't you?", "\"Yes, I put it in my pocket for a moment while my hands were full. I did not take it anywhere.\""),
               .cross("You were in this court before, in {PRIORDATE}, over pills, weren't you?", "\"Yes, I was, and I know how that looks. That is why I would never risk a job like this.\""),
               .cross("Twelve tablets were in your bag, weren't they?", "\"Yes, that is what the deputy found. I cannot explain it, and I did not put them there.\""),
               .cross("You did not mention the bottle to the dentist, did you?", "\"No, I did not, and I regret that. I thought there was nothing to mention.\""),
               .cross("You had the key that day, didn't you?", "\"Yes, I did. That is how I opened the cabinet to restock it.\"")],
        openings: ("A dental office counted forty hydrocodone tablets missing, and its own camera shows {D}, an assistant, opening the locked cabinet and pocketing a bottle. A deputy found twelve tablets in {D.his} bag, and {DL} was in this court before in {PRIORDATE} for {PRIOR}.", "The defense will present an assistant who was restocking with full hands and a dentist whose own count log was already off by ten the week before. A pocket and a bag do not prove a theft."),
        closings: ("The camera shows the cabinet opened and a bottle pocketed, and the bag held twelve tablets. {D} had the key, and {D.he} was in this court before over pills.", "The dentist's own count was off by ten tablets the week before. A pocket used while carrying supplies is not a theft, and the State has not shown intent."),
        timeline: [(-7, "The dentist's count log is off by ten tablets."), (0, "{D} opens the locked cabinet and pockets a bottle while restocking, on camera."), (0, "The dentist counts forty hydrocodone tablets missing."), (1, "A deputy finds twelve hydrocodone tablets in {D}'s bag.")],
        identified: "An office camera.",
        mood: .wantsConviction)

    static let longDriveAgain2 = SmallCases.make(
        key: "story.followup.longDriveAgain2",
        category: .family,
        headlines: ["Former Partner Follows Victim to Airport Lot Despite No-Contact Order", "Defendant From Kidnapping Case Violates Protective Order"],
        law: "dvpoViolation",
        spec: "Knowingly violated a valid domestic violence protective order by following {V} and approaching {V.him}, on {DATE}.",
        ages: 26...42,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} followed {V} to an airport parking lot on {DATE}, in violation of a protective order, and stood by {V}'s car until security came. {DL} says it was a public place and a coincidence.",
        state: [E(.document, 3, "Protective Order", "An order barring contact and approach."), E(.video, 3, "Lot Camera", "{D} walks to {V}'s car and waits there.")],
        defense: [E(.statement, 1, "Coincidence", "{DL} says {D.he} was catching a flight.")],
        role: "Airport security officer",
        exam: [.direct("What is your job at the airport?", "\"I am a security officer assigned to the parking lots. I patrol on foot and watch the lot cameras from the booth.\""),
               .direct("What did you see that day?", "\"I saw {DL} standing beside {V}'s car in the long-term lot. {D.He} was just standing there, close to the driver's door, not moving.\""),
               .direct("How did {V} react?", "\"{V} came out of the terminal, saw {DL} at the car, and stopped. {V.He} was shaking and asked me to call deputies.\""),
               .direct("What does the lot camera show?", "\"It shows {DL} walking across the lot directly to {V}'s car and waiting there. {D.He} does not look at any other car.\""),
               .direct("How long did {DL} wait?", "\"About fifteen minutes before {V} came out. {D.He} did not move the whole time.\""),
               .direct("Did you know about an order?", "\"{V} told me there was a protective order. A deputy confirmed it and showed me the order barring contact and approach.\""),
               .direct("What did you do?", "\"I stayed with {V}, called the sheriff's office, and kept an eye on {DL} until deputies came. {D.He} did not leave.\""),
               .cross("Was {DL} flying out that day?", "\"No ticket was found on {D.him}. I checked with the airline desk, and they could not find a booking in {D.his} name.\""),
               .cross("Is the long-term lot open to the public?", "\"Yes, anyone can park or walk there. It is a public lot.\""),
               .cross("Did {DL} say anything to {V}?", "\"Not that I heard. {D.He} did not say a word, and {V} stayed back.\""),
               .cross("Did {DL} touch the car?", "\"No, I did not see {D.him} touch it. {D.He} stood near it with {D.his} hands at {D.his} sides.\""),
               .cross("Did {DL} leave when told to?", "\"Yes. When the deputies told {D.him} to leave, {D.he} went without argument.\"")],
        theory: ("{D} approached a protected person at an airport parking lot and waited by {V.his} car.", "{D} was a traveler in a public lot who ended up near a car without knowing whose it was."),
        allocution: "\"I was at the airport to catch a flight, and I'm sorry that I ended up near {V}'s car. I know there's an order, and I've been in this courtroom before. It was a public place, and I didn't follow anyone. I'll stay far away from {V.him} from now on.\"",
        truths: ("{DL} had a prior case in this court and tracked {V}'s flight on a phone app.", "{DL}'s ticket was on a second phone that was seized later."),
        defendant: [.direct("Why were you at the airport?", "\"I was there to catch a flight. I have a ticket on my phone, and I can show it to the court.\""),
               .direct("Did you know {V} was at the airport?", "\"No, I had no idea. I did not follow {V.him} and I did not know {V.he} would be there.\""),
               .direct("Why were you standing by that car?", "\"I was waiting for a friend to give me a ride to the terminal. I did not know the car was {V.his} until {V.he} came out.\""),
               .direct("Did you touch the car or speak to {V}?", "\"No, I did not touch it, and I did not say anything. I stayed where I was.\""),
               .direct("What did you do when the deputies came?", "\"I told them about my flight and left when they asked. I did not argue.\""),
               .direct("What do you regret?", "\"I regret being anywhere near {V.him}. I know there is an order, and I will stay far away.\""),
               .cross("You knew about the protective order, didn't you?", "\"Yes, I did, and I did not break it on purpose. That is why I left when the deputies asked.\""),
               .cross("You were in this court before, in {PRIORDATE}, weren't you?", "\"Yes, I was, and I know that people think I follow {V.him}. I did not this time.\""),
               .cross("You had no ticket on paper, did you?", "\"I had it on my phone, and the airline would not find it that day. I have it now.\""),
               .cross("You tracked {V}'s flight on a phone app, didn't you?", "\"No, I did not. I never used an app to follow anyone.\""),
               .cross("You waited by the car for fifteen minutes, didn't you?", "\"Yes, I did, because I thought my friend would come. I did not know whose car it was.\"")],
        openings: ("A protective order barred {D} from contact with and approach to {V}. A lot camera shows {DL} walking directly to {V}'s car at the airport and waiting there until {V} came out, and no ticket for {D} was found.", "The defense will present a traveler in a public lot who had a ticket on a phone and who left when told. A coincidence, even an unlucky one, is not a violation of an order."),
        closings: ("The order barred approach, the camera shows {D} walk straight to {V}'s car, and no ticket was found. {D} had been in this court before.", "A public lot, a ticket on a phone, and a person who left at once when asked. The State has not shown that {D} knew whose car it was."),
        timeline: [(-30, "A protective order is entered barring {D} from contact with and approach to {V}."), (0, "{D} walks across the airport long-term lot to {V}'s car and waits."), (0, "{V} comes out of the terminal, sees {D}, and asks security to call deputies."), (0, "Deputies tell {D} to leave, and {D} goes.")],
        identified: "A lot camera.",
        mood: .wantsConviction)

    static let mercyKillingAgain2 = SmallCases.make(
        key: "story.followup.mercyKillingAgain2",
        category: .family,
        headlines: ["Elderly Friend Charged After Ill Neighbor's Fatal Insulin Dose", "Defendant From Mercy Case Faces Manslaughter Charge"],
        law: "volManslaughter",
        threshold: 7,
        spec: "Unlawfully killed {V} without malice, on {DATE}.",
        ages: 84...92,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}, a terminally ill friend, died on {DATE} of a large insulin dose given at {V}'s home. {D} told deputies {V} had begged for it. {DL} says {V} had asked months before and signed a note.",
        state: [E(.forensic, 3, "Toxicology", "A massive insulin dose."), E(.statement, 3, "Hospice Nurse", "{D} visited that afternoon.")],
        defense: [E(.document, 2, "Signed Note", "A note in {V}'s hand asking for relief.")],
        role: "Sheriff's detective",
        exam: [.direct("What is your position?", "\"I am a detective with the sheriff's office. I was assigned to the death of {V} and worked the case from the first call.\""),
               .direct("How did {V} die?", "\"{V} died at home of a large insulin overdose. The medical examiner's toxicology report shows a massive dose, well beyond anything prescribed.\""),
               .direct("Who was with {V}?", "\"{DL} was there that afternoon, and the hospice nurse confirms {D.he} visited. No one else was in the home at the time.\""),
               .direct("What did {DL} tell you?", "\"{D.He} told me {V} had begged for the dose, and that {D.he} gave it. {D.He} did not try to hide what had happened.\""),
               .direct("Was {V} terminally ill?", "\"Yes, {V} had a terminal illness and was under hospice care. The hospice records say so.\""),
               .direct("What did you find in the home?", "\"A signed note in {V}'s handwriting asking for relief, and the insulin supplies. I photographed all of it.\""),
               .direct("What was the relationship?", "\"They were friends, according to the neighbors and the nurse. {DL} visited often, and {V} seemed to trust {D.him}.\""),
               .cross("Did {V} sign a note asking for this?", "\"A note in {V}'s hand asks for relief from suffering. It does not name {DL} or a method.\""),
               .cross("When was the note written?", "\"The note is not dated. A neighbor says it was written months earlier and witnessed.\""),
               .cross("Did {DL} call for help afterward?", "\"Yes, {D.he} called the hospice nurse and stayed until the nurse arrived.\""),
               .cross("Was {V} in pain?", "\"The hospice records say {V} was in significant pain and had asked about ending it.\""),
               .cross("You cannot say what {V} wanted that day, can you?", "\"No, only what the note and {DL} say. I did not speak with {V}.\"")],
        theory: ("{D} gave a fatal insulin dose to a terminally ill friend.", "{D} acted at a friend's repeated, written request."),
        allocution: "\"I gave my friend that dose because {V.he} asked me to, months before, and signed a note. I've been in this courtroom before, and I know what I did. I loved {V.him}, and I sat with {V.him} until the end. I'm sorry for the family's pain, and I'll accept the court's decision.\"",
        truths: ("{DL} had a prior case in this court and had said 'it is my duty.'", "The note was witnessed by a neighbor months earlier."),
        defendant: [.direct("What did you do that afternoon?", "\"I gave {V} the dose. {V.He} had asked me to, months before, and {V.he} asked again that day.\""),
               .direct("Why did you do it?", "\"{V.He} was in terrible pain and had no hope of getting better. {V.He} begged me, and I could not say no.\""),
               .direct("Was there a note?", "\"Yes, a note in {V}'s own hand asking for relief, signed months earlier. A neighbor witnessed it.\""),
               .direct("What did you do afterward?", "\"I sat with {V.him} until the end, and then I called the hospice nurse. I did not leave.\""),
               .direct("How did you feel?", "\"I felt that I was doing what a friend should do. I also felt that I had crossed a line I could not take back.\""),
               .direct("What would you tell {V}'s family?", "\"I am sorry for their pain. I loved {V.him}, and I did what I thought {V.he} wanted.\""),
               .cross("You gave the fatal dose, didn't you?", "\"Yes, I did, and I will not say otherwise. I knew what it would do.\""),
               .cross("You were in this court before, in {PRIORDATE}, weren't you?", "\"Yes, I was, and I know what I did was against the law.\""),
               .cross("The note does not mention you, does it?", "\"No, but {V.he} told me what {V.he} wanted. I took {V.his} word.\""),
               .cross("You told someone it was your duty, didn't you?", "\"I said something like that, and I believed it at the time. I do not believe it now.\""),
               .cross("You did not call anyone before the dose, did you?", "\"No, I did not, and I should have asked for help.\"")],
        openings: ("{V}, a terminally ill friend, died at home of a massive insulin overdose. {D} was there, told deputies that {V} had begged for it, and {DL} was in this court before in {PRIORDATE} for {PRIOR}.", "The defense will present a signed note in {V}'s own hand and a friend who acted out of love. {D} never hid what {D.he} did and stayed until the end."),
        closings: ("{V} died of a massive insulin dose given by {D}, and the law does not make exceptions for a friend's request. {D} was in this court before.", "A signed note, a terminal illness, and a friend who stayed to the end. The State must prove that {D} acted with the intent the law requires."),
        timeline: [(-90, "{V} writes and signs a note asking for relief from {V.his} illness, and a neighbor witnesses it."), (0, "Afternoon: {D} visits {V} at home and gives the insulin dose."), (0, "{D} stays with {V} until the end and then calls the hospice nurse."), (1, "A detective interviews {D}, who says {V} had begged for it.")],
        identified: "{D} told deputies.",
        mood: .sympathetic,
        genders: ["D": .male])
}
